@Component
struct RestoreView {
  @State retryAllowed: boolean = false
  @State statusMessage: string = ''
  enableRecovery(): void {
    this.retryAllowed = true
    this.statusMessage = 'capacity recovery available'
  }
  build() {
    Button('Restore capacity').onClick(() => this.enableRecovery())
    Text(this.statusMessage)
  }
}

